29: 
30:     public static final int MAX_PROFILE_CHARS = 12_000;
31:     private static final long MAX_FILE_BYTES = 1_000_000;
32:     private static final Pattern USER_PROFILE_SECTION = Pattern.compile(
33:             "(?ms)^##\\s+User Profile\\s*$\\R(.*?)(?=^##\\s+|\\z)");
34: 
35:     private final AgentStorageProperties storageProperties;
36:     private final TokenCounter tokenCounter;
37:     private final ObjectMapper objectMapper;
38: 
39:     /** 读取当前用户可见的画像；显式空文件会阻止旧画像回退。 */
40:     public PersonalContextProfile get(String userId) {
41:         Path explicitFile = storageProperties.personalContextProfileFile(userId);
42:         String content;
43:         String source;
44:         if (isSafeReadableFile(userId, explicitFile)) {
45:             content = readSmallFile(userId, explicitFile);
46:             source = "explicit";
47:         } else {
48:             content = extractLegacyProfile(readSmallFile(userId,
49:                     storageProperties.userWorkspaceDirectory(userId).resolve("MEMORY.md")));
50:             source = content == null || content.isBlank() ? "empty" : "legacy";
51:         }
52:         String normalized = content == null ? "" : content.strip();
53:         Settings settings = readSettings(userId);
54:         return new PersonalContextProfile(settings.enabled(), settings.maintenanceEnabled(),
55:                 normalized, source, tokenCounter.count(normalized), revision(normalized));
56:     }
57: 
58:     /** 保存显式画像，内容在注入时仍会受独立 Token 预算裁剪。 */
59:     public synchronized PersonalContextProfile save(String userId, String content) {
60:         String normalized = content == null ? "" : content.strip();
61:         if (normalized.length() > MAX_PROFILE_CHARS) {
62:             throw new IllegalArgumentException("个人画像不能超过 " + MAX_PROFILE_CHARS + " 个字符");
63:         }
64:         writeAtomically(storageProperties.personalContextProfileFile(userId), normalized);
65:         return get(userId);
66:     }
67: 
68:     /** 清空自动注入画像；保留显式空文件以避免兼容来源重新出现。 */
69:     public synchronized PersonalContextProfile clear(String userId) {
70:         writeAtomically(storageProperties.personalContextProfileFile(userId), "");
71:         return get(userId);
72:     }
73: 
74:     /** 开启或暂停画像与相关记忆自动注入，不删除已有内容。 */
75:     public synchronized PersonalContextProfile setEnabled(String userId, boolean enabled) {
76:         Settings current = readSettings(userId);
77:         writeSettings(userId, new Settings(enabled, current.maintenanceEnabled()));
78:         return get(userId);
79:     }
80: 
81:     /** 开启或关闭“自动生成提案、用户确认后应用”的辅助维护。 */
82:     public synchronized PersonalContextProfile setMaintenanceEnabled(String userId, boolean enabled) {
83:         Settings current = readSettings(userId);
84:         writeSettings(userId, new Settings(current.enabled(), enabled));
85:         return get(userId);
86:     }
87: 
88:     private Settings readSettings(String userId) {
89:         String json = readSmallFile(userId, storageProperties.personalContextSettingsFile(userId));
90:         if (json == null || json.isBlank()) return Settings.defaults();
91:         try {
92:             JsonNode root = objectMapper.readTree(json);
93:             JsonNode enabled = root.get("enabled");
94:             JsonNode maintenanceEnabled = root.get("maintenanceEnabled");
95:             return new Settings(
96:                     enabled == null || !enabled.isBoolean() || enabled.asBoolean(),
97:                     maintenanceEnabled != null && maintenanceEnabled.isBoolean()
98:                             && maintenanceEnabled.asBoolean());
99:         } catch (IOException exception) {
100:             log.warn("读取个人上下文设置失败，按启用处理：userId={}", userId, exception);
101:             return Settings.defaults();
102:         }
103:     }
104: 
105:     private void writeSettings(String userId, Settings settings) {
106:         try {
107:             writeAtomically(storageProperties.personalContextSettingsFile(userId),
108:                     objectMapper.writeValueAsString(Map.of(
109:                             "enabled", settings.enabled(),
110:                             "maintenanceEnabled", settings.maintenanceEnabled())));
111:         } catch (IOException exception) {
112:             throw new IllegalStateException("保存个人上下文设置失败", exception);
113:         }
114:     }
115: 
116:     private String revision(String content) {
117:         try {
118:             byte[] digest = MessageDigest.getInstance("SHA-256")
119:                     .digest(content.getBytes(StandardCharsets.UTF_8));
120:             return HexFormat.of().formatHex(digest, 0, 12);
121:         } catch (NoSuchAlgorithmException exception) {
122:             throw new IllegalStateException("当前运行环境缺少 SHA-256", exception);
123:         }
124:     }
125: 
126:     private String extractLegacyProfile(String markdown) {
127:         if (markdown == null) return null;
128:         Matcher matcher = USER_PROFILE_SECTION.matcher(markdown);
129:         return matcher.find() ? matcher.group(1).strip() : null;
130:     }
131: 
132:     private String readSmallFile(String userId, Path path) {
133:         try {
134:             if (!isSafeReadableFile(userId, path)
135:                     || Files.size(path) > MAX_FILE_BYTES) return null;
136:             return Files.readString(path, StandardCharsets.UTF_8);
137:         } catch (IOException exception) {
138:             log.warn("读取个人上下文文件失败：path={}", path, exception);
139:             return null;
140:         }
141:     }
142: 
143:     private void writeAtomically(Path target, String content) {
144:         try {
145:             Path userWorkspace = target.getParent().getParent();
146:             if (Files.isSymbolicLink(userWorkspace) || Files.isSymbolicLink(target.getParent())) {
147:                 throw new IllegalStateException("个人上下文目录不能是符号链接");
148:             }
149:             Files.createDirectories(target.getParent());
150:             if (Files.isSymbolicLink(target)) throw new IllegalStateException("个人上下文文件不能是符号链接");
151:             Path temporary = Files.createTempFile(target.getParent(), ".personal-context-", ".tmp");
152:             try {
153:                 Files.writeString(temporary, content, StandardCharsets.UTF_8);
154:                 try {
155:                     Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE,
156:                             StandardCopyOption.REPLACE_EXISTING);
157:                 } catch (AtomicMoveNotSupportedException exception) {
158:                     Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
159:                 }
160:             } finally {
161:                 Files.deleteIfExists(temporary);
162:             }
163:         } catch (IOException exception) {
164:             throw new IllegalStateException("保存个人上下文失败", exception);
165:         }
166:     }
167: 
168:     private boolean isSafeReadableFile(String userId, Path path) {
169:         Path userWorkspace = storageProperties.userWorkspaceDirectory(userId);
170:         return !Files.isSymbolicLink(userWorkspace)
171:                 && !Files.isSymbolicLink(path.getParent())
172:                 && !Files.isSymbolicLink(path)
173:                 && Files.isRegularFile(path);
174:     }
175: 
176:     private record Settings(boolean enabled, boolean maintenanceEnabled) {
177:         private static Settings defaults() {
178:             return new Settings(true, false);
179:         }
180:     }
181: }

