164:         ProfileProposal proposal = new ProfileProposal(
165:                 UUID.randomUUID().toString(),
166:                 current.revision(),
167:                 bundle.fingerprint(),
168:                 Instant.now(),
169:                 generated.summary(),
170:                 generated.proposedProfile(),
171:                 generated.changes());
172:         writeJson(storageProperties.personalContextPendingProposalFile(userId), proposal);
173:         writeState(userId, new MaintenanceState(bundle.fingerprint(), Instant.now(), "proposal_ready"));
