37:     /**
38:      * 读取一条会话的所有完整消息
39:      * @param sessionId
40:      * @return
41:      */
42:     public synchronized List<TranscriptMessageDto> list(String sessionId) {
43:         Path transcriptFile = storageProperties.transcriptFile(sessionId);
44:         if (!Files.exists(transcriptFile)) {
45:             return List.of();
46:         }
47: 
48:         List<TranscriptMessageDto> messages = new ArrayList<>();
49: 
50:         try (var lines = Files.lines(transcriptFile, StandardCharsets.UTF_8)) {
51:             lines.filter(line -> !line.isBlank()).forEach(line -> {
52:                 try {
53:                     messages.add(objectMapper.readValue(line, TranscriptMessageDto.class));
54:                 } catch (IOException e) {
55:                     log.warn("跳过损坏的会话消息记录：sessionId={}",sessionId);
56:                 }
57:             });
58:             return List.copyOf(messages);
59:         } catch (IOException e) {
60:             throw new IllegalArgumentException("读取会话消息记录失败", e);
61:         }
62:     }
