36:     /** 短事务建立工作项，生成在 worker 中进行；同版本重放复用结果。 */
37:     public ContentView prepare(String owner, Prepare input) {
38:         try (var lease = barrier.enter()) {
39:             return new TransactionTemplate(transactions).execute(tx -> {
40:                 var s = authorization.require(owner);
41:                 LocalDate today = automationClock.instant().atZone(ZoneId.of(s.timezone())).toLocalDate();
42:                 if (input == null || input.day() == null || input.day().isAfter(today)
43:                         || input.day().isBefore(today.minusDays(s.historyDays() - 1L)))
44:                     throw new IllegalArgumentException("复盘日期超出已授权窗口");
45:                 var old = repository.latest(owner, input.day());
46:                 boolean currentGrant = old.isPresent() && old.get().grantId().equals(s.grantId());
47:                 boolean reusable = currentGrant && Set.of("READY", "PENDING", "RUNNING").contains(old.get().state());
48:                 if ((reusable && !input.supplement())
49:                         || (currentGrant && input.supplement() && old.get().version() == input.expectedVersion() + 1))
50:                     return view(old.get());
51:                 int expected = (!currentGrant || !reusable) && !input.supplement()
52:                         ? old.map(Content::version).orElse(0) : input.expectedVersion();
53:                 if (expected != old.map(Content::version).orElse(0))
54:                     throw new IllegalArgumentException("复盘版本已变化，请刷新");
55:                 if (currentGrant && Set.of("PENDING", "RUNNING").contains(old.get().state()))
56:                     throw new IllegalArgumentException("当前版本尚在生成，请稍后补充");
57:                 Instant now = automationClock.instant();
58:                 var c = new Content(UUID.randomUUID().toString(), owner, input.day(), s.timezone(), expected + 1,
59:                         s.grantId(), s.revision(), "PENDING", now, availableAt(now, s.timezone()), now,
60:                         lease.generation(), List.of(), List.of(), "等待按授权范围采集", null, List.of(), "");
61:                 repository.insert(c);
62:                 return view(c);
63:             });
64:         }
65:     }
66:     /** 23:30 只用于本域顺延；凌晨仍属于前一天复盘的延后窗口。 */
67:     public static Instant availableAt(Instant instant, String timezone) {
68:         var local = instant.atZone(ZoneId.of(timezone));
69:         if (!local.toLocalTime().isBefore(LocalTime.of(23, 30)))
70:             return local.toLocalDate().plusDays(1).atTime(12, 0).atZone(local.getZone()).toInstant();
71:         if (local.getHour() < 12) return local.toLocalDate().atTime(12, 0).atZone(local.getZone()).toInstant();
72:         return instant;
73:     }
