244:     private String control(Task command, String text) {
245:         if (text.startsWith("/review ")) {
246:             if (reviewReplies == null || reviewReplies.getIfUnique() == null) return "当前后端不支持生活复盘补充，请到桌面查看。";
247:             String rest = text.substring("/review ".length()).strip();
248:             if (rest.matches("(?s)[a-f0-9-]{36} .+")) {
249:                 String[] parts = rest.split(" ", 2);
250:                 return reviewReplies.getIfUnique().reply(currentUser.currentUserId(), parts[0], command.id(), parts[1]);
251:             }
252:             return reviewReplies.getIfUnique().reply(currentUser.currentUserId(), "latest", command.id(), rest);
253:         }
254:         List<Task> tasks = store.snapshot().tasks().stream().filter(t -> t.conversation().equals(command.conversation())
255:                 && !t.id().equals(command.id())).toList();
256:         if (text.equals("/stop")) {
257:             Task active = tasks.stream().filter(t -> t.state() == Execution.RUNNING || t.state() == Execution.STOPPING).findFirst().orElse(null);
258:             if (active == null) return "当前没有正在执行的任务。";
259:             Running execution = running.get(active.id());
260:             if (execution != null) execution.control.stop("user");
261:             store.update(active.id(), t -> t.toBuilder().state(Execution.STOPPING).build());
262:             delivery.discardNotices(active.id());
263:             return "正在停止当前任务；等待队列保留，如需清空请发送 /clear。";
264:         }
265:         if (text.equals("/clear")) {
266:             int count = 0;
267:             for (Task task : tasks) if (task.state() == Execution.QUEUED) {
268:                 finish(task.id(), Execution.CLEARED, "本条等待任务已清空，未执行。"); count++;
269:             }
270:             return "已清空 " + count + " 条等待消息，正在执行的任务不受影响。";
271:         }
272:         if (text.equals("/new")) {
273:             if (tasks.stream().anyMatch(t -> t.state().active())) return "还有任务正在执行或排队，请先 /stop 和 /clear，再新建对话。";
274:             String session = sessions.createFeishuSession().id();
275:             store.bind(command.conversation(), session);
276:             return "已建立新对话，之后的消息将使用新的上下文。";
277:         }
278:         String id = text.substring(text.indexOf(' ') + 1);
279:         Task target = store.task(id);
280:         if (target == null || !target.conversation().equals(command.conversation())) return "未找到属于当前聊天的任务。";
281:         boolean unknown = target.parts().stream().anyMatch(p -> p.status() == Delivery.UNKNOWN);
282:         if (text.startsWith("/ack")) {
283:             if (!unknown && target.parts().stream().noneMatch(p -> p.status() == Delivery.FAILED)) {
284:                 return "该任务没有需要确认的待定投递。";
285:             }
286:             // 只在用户亲自确认已经看到内容时使用：不重发、不重执行，只解除该会话的投递暂停。
287:             delivery.acknowledge(id);
288:             return "已确认该回复无需补发，该会话已恢复自动发送。";
289:         }
290:         if (unknown && text.startsWith("/retry")) return "该回复可能已经送达。补发可能重复；确认后请发送 /resend " + id;
291:         if (target.parts().stream().noneMatch(p -> p.status() == Delivery.FAILED || p.status() == Delivery.UNKNOWN)) return "该任务没有需要补发的失败回复。";
292:         delivery.retry(id, text.startsWith("/resend"));
293:         return "已安排补发保存的回复，不会重新执行 Agent 或工具。";
294:     }
