333:     private void dispatch() {
334:         if (closed || faulted || (resetBarrier != null && resetBarrier.blocked())) return;
335:         Set<String> occupied = new HashSet<>();
336:         for (String id : running.keySet()) occupied.add(store.task(id).conversation());
337:         for (Task task : store.snapshot().tasks()) {
338:             if (task.state() != Execution.QUEUED) continue;
339:             if (clock.millis() - task.acceptedAt() >= config.queueTimeoutSeconds() * 1000L) {
340:                 finish(task.id(), Execution.EXPIRED, "等待时间过长，本条尚未执行，请重新发送。"); continue;
341:             }
342:             if (running.size() >= config.maxConcurrentRuns() || occupied.contains(task.conversation())) continue;
343:             try {
344:                 String session = resolveSession(task.conversation());
345:                 Running execution = new Running(new FeishuAgentRunner.Control(), nanoTime.getAsLong(), config.heartbeatSeconds());
346:                 store.update(task.id(), t -> t.toBuilder().state(Execution.RUNNING).sessionId(session)
347:                         .startedAt(clock.millis()).nextHeartbeatAt(clock.millis() + config.heartbeatSeconds() * 1000L).build());
348:                 running.put(task.id(), execution); occupied.add(task.conversation());
349:                 if ("等待执行".equals(task.stage())) delivery.notice(task, "started", "已开始处理你的这条消息。", true, () -> active(task.id()));
350:                 Task started = store.task(task.id());
351:                 log.info("飞书任务开始：taskId={}, runId={}, queueMs={}", task.id(), task.runId(),
352:                         Math.max(0, clock.millis() - task.acceptedAt()));
353:                 workers.execute(() -> execute(started, execution));
354:             } catch (RuntimeException exception) {
355:                 running.remove(task.id());
356:                 log.warn("飞书任务启动失败：taskId={}, errorType={}", task.id(), exception.getClass().getSimpleName());
357:                 finish(task.id(), Execution.FAILED, "任务未能启动，请检查桌面端会话状态后重试。");
358:             }
359:         }
360:     }
