426:         for (int i = 0; i < chunks.size(); i++) parts.add(Part.builder().id(stableId(taskId + ":part:" + i))
427:                 .text(chunks.get(i)).status(Delivery.PENDING).build());
428:         store.update(taskId, task -> task.toBuilder().state(state).input(null).finishedAt(clock.millis()).parts(parts).build());
429:         delivery.discardNotices(taskId);
430:         log.info("飞书任务已保存终态：taskId={}, state={}, outputLength={}, parts={}",
431:                 taskId, state, text == null ? 0 : text.length(), parts.size());
432:     }
433: 
434:     private boolean active(String id) { Task task = store.task(id); return task != null && task.state().active(); }
435: 
436:     private void recover() {
437:         for (Task task : store.snapshot().tasks()) {
438:             if (task.state().active()) {
439:                 TranscriptMessageDto saved = task.sessionId() == null ? null : transcripts.list(task.sessionId()).stream()
440:                         .filter(m -> task.turnId().equals(m.turnId()) && m.role() == TranscriptMessageDto.MessageRole.ASSISTANT)
441:                         .findFirst().orElse(null);
442:                 if (saved != null && saved.status() == TranscriptMessageDto.MessageStatus.COMPLETED) {
443:                     finish(task.id(), Execution.SUCCEEDED, saved.content());
444:                 } else finish(task.id(), Execution.INTERRUPTED, "服务已重启，本条任务已中断且不会自动重新执行。请检查实际结果后决定是否重新发起。");
445:             } else if (task.parts().stream().anyMatch(p -> p.status() == Delivery.SENDING)) {
446:                 store.update(task.id(), t -> t.toBuilder().parts(t.parts().stream().map(part -> part.status() == Delivery.SENDING
447:                         ? part.toBuilder().status(Delivery.UNKNOWN).errorCode("restart_during_send").build() : part).toList()).build());
448:                 delivery.notice(task, "recovery", "服务曾在发送回复时中断，发送状态不确定，完整结果已保留。补发可能重复；确认后请发送 /resend "
449:                         + task.id(), true, () -> true);
450:             }
451:         }
452:     }
453: 
454:     private void requireClosed() {
455:         if (!closed || (workers != null && !workers.isTerminated()) || (delivery != null && !delivery.terminated())) {
456:             throw new IllegalStateException("飞书渠道仍在运行或收尾，禁止并行启动");
457:         }
458:     }
459: 
460:     private synchronized void freeze() {
461:         if (faulted) return;
462:         faulted = true;
463:         running.values().forEach(execution -> execution.control.stop("storage_failure"));
464:         log.error("飞书渠道已停止受理及投递，请修复本地状态后重启");
465:     }
466: 
467:     @Override
468:     public void close() {
469:         synchronized (this) {
470:             if (closed) return;
471:             closed = true;
472:             if (scheduler != null) scheduler.shutdownNow();
473:             running.values().forEach(execution -> execution.control.stop("shutdown"));
474:             workers.shutdown();
475:         }
476:         try {
477:             if (!workers.awaitTermination(15, TimeUnit.SECONDS)) workers.shutdownNow();
478:         } catch (InterruptedException exception) { workers.shutdownNow(); Thread.currentThread().interrupt(); }
479:         delivery.close();
480:         if (workers.isTerminated() && delivery.terminated()) {
481:             try { store.close(); } catch (IOException exception) { log.warn("飞书账本锁释放失败"); }
482:         } else log.error("仍有任务或发送未确认结束，保留渠道独占锁直到进程退出，禁止并行启动");
483:     }
484: 
485:     private static final class Running {
486:         final FeishuAgentRunner.Control control;
487:         final long started;
488:         long nextHeartbeat;
489:         Running(FeishuAgentRunner.Control control, long started, int intervalSeconds) {
490:             this.control = control; this.started = started;
491:             this.nextHeartbeat = started + TimeUnit.SECONDS.toNanos(intervalSeconds);
492:         }
493:     }
