11: /** 显式目标与用户反馈的独立可选来源；不借用旧复盘或聊天记忆许可。 */
12: @Service
13: @RequiredArgsConstructor
14: public class LifePersonalMaterialService {
15:     private final ReviewGoalService goals;
16:     private final LifeReviewRepository repository;
17:     private final TokenCounter counter;
18:     /** 目标最多300、反馈最多500本地估算Token；超预算完整跳过，不悄悄截去用户约束。 */
19:     public List<Material> collect(Settings s, Instant cutoff) {
20:         if (!s.sources().contains("GOALS")) return List.of();
21:         List<Material> result = new ArrayList<>();
22:         int goalTokens = 0, feedbackTokens = 0;
23:         for (var g : goals.list(s.owner()).stream().filter(g -> g.state().equals("ACTIVE")).limit(3).toList()) {
24:             String text = "用户明确目标：" + g.title() + "；约束：" + g.constraintText() + "；衡量：" + g.successCriterion();
25:             int tokens = counter.count(text) + 80;
26:             if (goalTokens + tokens > 300 || g.updatedAt().isAfter(cutoff)) continue;
27:             goalTokens += tokens;
28:             result.add(new Material("goal-" + g.id(), "USER_GOAL", g.id(), g.updatedAt().toString(), text, false));
29:         }
30:         for (var material : repository.feedbackMaterials(s.owner(), cutoff.minus(Duration.ofDays(s.historyDays())), cutoff)) {
31:             int tokens = counter.count(material.text()) + 80;
32:             if (feedbackTokens + tokens > 500) continue;
33:             feedbackTokens += tokens;
34:             result.add(material);
35:         }
36:         return List.copyOf(result);
37:     }
38:     /** 发布时重新核对当前目标和反馈，用户修正后不继续发布旧理解。 */
39:     public void verify(Settings s, List<Material> values) {
40:         if (values.stream().noneMatch(m -> m.kind().equals("USER_GOAL") || m.kind().equals("USER_FEEDBACK"))) return;
41:         var current = goals.list(s.owner()).stream().filter(g -> g.state().equals("ACTIVE")).toList();
42:         var candidates = repository.candidates(s.owner());
43:         for (var m : values) {
44:             if (m.kind().equals("USER_GOAL") && current.stream().noneMatch(g -> g.id().equals(m.sourceId()) && m.text().equals(
45:                     "用户明确目标：" + g.title() + "；约束：" + g.constraintText() + "；衡量：" + g.successCriterion())))
46:                 throw new IllegalArgumentException("用户复盘目标已变化");
47:             if (m.kind().equals("USER_FEEDBACK") && candidates.stream().noneMatch(c -> c.id().equals(m.sourceId())
48:                     && m.text().equals("用户对主动主题 " + c.topic() + " 的明确反馈：" + c.feedback())))
49:                 throw new IllegalArgumentException("用户复盘反馈已变化");
50:         }
51:     }
52: }

