16: /** 在新用户轮次开始前，为上次进程遗留的未完成工具调用补齐安全失败结果。 */
17: @Component
18: public class OrphanedToolCallRecovery {
19: 
20:     /**
21:      * 只处理最后一条 assistant 消息中缺少结果的工具；正常 HITL 恢复不得调用此方法。
22:      *
23:      * @return 新增的失败结果数量
24:      */
25:     public int recover(AgentState state, String agentName) {
26:         List<Msg> context = state.contextMutable();
27:         int lastAssistantIndex = -1;
28:         Msg lastAssistant = null;
29:         for (int index = context.size() - 1; index >= 0; index--) {
30:             if (context.get(index).getRole() == MsgRole.ASSISTANT) {
31:                 lastAssistantIndex = index;
32:                 lastAssistant = context.get(index);
33:                 break;
34:             }
35:         }
36:         if (lastAssistant == null) return 0;
37: 
38:         Set<String> completedIds = new HashSet<>();
39:         for (int i = lastAssistantIndex + 1; i < context.size(); i++) {
40:             context.get(i).getContentBlocks(ToolResultBlock.class).stream()
41:                     .map(ToolResultBlock::getId)
42:                     .forEach(completedIds::add);
43:         }
44:         List<ToolUseBlock> orphaned = lastAssistant.getContentBlocks(ToolUseBlock.class).stream()
45:                 .filter(tool -> !completedIds.contains(tool.getId()))
46:                 .toList();
47: 
48:         for (ToolUseBlock tool : orphaned) {
49:             ToolResultBlock result = ToolResultBlock
50:                     .text("[ERROR] Previous tool execution failed or was interrupted. Tool: " + tool.getName())
51:                     .withState(ToolResultState.ERROR);
52:             context.add(ToolResultMessageBuilder.buildToolResultMsg(result, tool, agentName));
53:         }
54:         return orphaned.size();
55:     }
56: }

