198:     private void checkExpense(Settings s, ZonedDateTime local, Instant now) {
199:         if (!s.expenseSignalEnabled() || expenseAnalytics == null) return;
200:         String source = "expense";
201:         int minHour = repository.habit(s.owner())
202:                 .filter(h -> h.active() && now.isBefore(h.expiresAt()))
203:                 .map(Habit::availableHour)
204:                 .orElse(12);
205:         if (local.getHour() < minHour || !local.toLocalTime().isBefore(LocalTime.of(23, 30))) return;
206: 
207:         LocalDate today = local.toLocalDate();
208:         List<ExpenseEntry> entries = expenseAnalytics.reportExpenses(s.owner(), today.minusDays(28), today);
209:         if (entries == null || entries.isEmpty()) return;
210: 
211:         Map<String, List<ExpenseEntry>> byCurrency = new TreeMap<>();
212:         for (ExpenseEntry entry : entries) {
213:             if (entry.amount() == null || entry.amount().compareTo(BigDecimal.ZERO) <= 0) continue;
214:             String currency = (entry.currency() == null || entry.currency().isBlank()) ? "CNY" : entry.currency().strip();
215:             byCurrency.computeIfAbsent(currency, k -> new ArrayList<>()).add(entry);
216:         }
217: 
218:         for (Map.Entry<String, List<ExpenseEntry>> item : byCurrency.entrySet()) {
219:             String currency = item.getKey();
220:             List<ExpenseEntry> prior = new ArrayList<>();
221:             List<ExpenseEntry> todayEntries = new ArrayList<>();
222:             for (ExpenseEntry entry : item.getValue()) {
223:                 if (today.equals(entry.date())) {
224:                     todayEntries.add(entry);
225:                 } else if (entry.date() != null && entry.date().isBefore(today)) {
226:                     prior.add(entry);
227:                 }
228:             }
229:             if (todayEntries.isEmpty() || prior.isEmpty()) continue;
230: 
231:             long activePriorDays = prior.stream().map(ExpenseEntry::date).distinct().count();
232:             if (activePriorDays < MIN_PRIOR_EXPENSE_DAYS) continue;
233: 
234:             BigDecimal priorTotal = prior.stream()
235:                     .map(ExpenseEntry::amount)
236:                     .reduce(BigDecimal.ZERO, BigDecimal::add);
237:             BigDecimal dailyAvg = priorTotal.divide(BigDecimal.valueOf(activePriorDays), 2, RoundingMode.HALF_UP);
238:             BigDecimal todayTotal = todayEntries.stream()
239:                     .map(ExpenseEntry::amount)
240:                     .reduce(BigDecimal.ZERO, BigDecimal::add)
241:                     .setScale(2, RoundingMode.HALF_UP);
242:             BigDecimal threshold = dailyAvg.multiply(EXPENSE_SPIKE_MULTIPLIER).max(MIN_EXPENSE_ALERT_AMOUNT);
243:             if (todayTotal.compareTo(threshold) < 0) continue;
244: 
245:             String topCategory = resolveTopCategory(todayEntries);
246:             String dedupKey = "expense:" + today + ":" + currency;
