364:     private static boolean isMailMatching(String from, String subject, String whitelistStr, String keywordsStr) {
365:         boolean hasWhitelist = whitelistStr != null && !whitelistStr.isBlank();
366:         boolean hasKeywords = keywordsStr != null && !keywordsStr.isBlank();
367:         if (!hasWhitelist && !hasKeywords) {
368:             return true;
369:         }
370: 
371:         String lowerFrom = "";
372:         try {
373:             var addresses = InternetAddress.parse(from == null ? "" : from, true);
374:             if (addresses.length == 1) lowerFrom = addresses[0].getAddress().toLowerCase(Locale.ROOT);
375:         } catch (jakarta.mail.internet.AddressException invalid) {
376:             log.debug("邮件发件人地址格式无效，按非白名单处理");
377:         }
378:         String lowerSubject = subject == null ? "" : subject.toLowerCase(Locale.ROOT);
379: 
380:         if (hasWhitelist) {
381:             String[] senders = whitelistStr.split("[,，]");
382:             for (String s : senders) {
383:                 String trimmed = s.strip().toLowerCase(Locale.ROOT);
384:                 if (!trimmed.isEmpty() && lowerFrom.equals(trimmed)) {
385:                     return true;
386:                 }
387:             }
388:         }
389: 
390:         if (hasKeywords) {
391:             String[] keywords = keywordsStr.split("[,，]");
392:             for (String kw : keywords) {
393:                 String trimmed = kw.strip().toLowerCase(Locale.ROOT);
394:                 if (!trimmed.isEmpty() && lowerSubject.contains(trimmed)) {
395:                     return true;
396:                 }
397:             }
398:         }
399: 
400:         return false;
401:     }
