29: 
30:     public static final int MAX_PROFILE_CHARS = 12_000;
31:     private static final long MAX_FILE_BYTES = 1_000_000;
32:     private static final Pattern USER_PROFILE_SECTION = Pattern.compile(
33:             "(?ms)^##\\s+User Profile\\s*$\\R(.*?)(?=^##\\s+|\\z)");
34: 
