13: /** 单独有界后台线程；准备与投递分开，重启不自动重放在途模型或渠道请求。 */
14: @Slf4j
15: @Component
16: @RequiredArgsConstructor
17: public class LifeReviewRuntime {
18:     private final LifeReviewRepository repository;
19:     private final LifeReviewService reviews;
20:     private final LifeOutreachService outreach;
21:     private final ResetBarrier barrier;
22:     private final Clock automationClock;
23:     private final ScheduledExecutorService worker = Executors.newSingleThreadScheduledExecutor(r -> {
24:         Thread t = new Thread(r, "life-review-worker"); t.setDaemon(true); return t;
25:     });
26:     private final ScheduledExecutorService generationWorker = Executors.newSingleThreadScheduledExecutor(r -> {
27:         Thread t = new Thread(r, "life-review-generation"); t.setDaemon(true); return t;
28:     });
29:     @EventListener(ApplicationReadyEvent.class)
30:     /** 迁移就绪后恢复未知状态，再启动有界后台循环。 */
31:     public void start() {
32:         if (!barrier.blocked()) try (var lease = barrier.enter()) {
33:             repository.migrateMailSecrets();
34:             repository.recover();
35:         }
36:         worker.scheduleWithFixedDelay(this::tick, 2, 2, TimeUnit.SECONDS);
37:         generationWorker.scheduleWithFixedDelay(this::generate, 2, 2, TimeUnit.SECONDS);
38:     }
39:     /** 按授权准备每日内容和到期候选，重置保护期间跳过。 */
40:     public void tick() {
41:         if (barrier.blocked()) return;
42:         try (var lease = barrier.enter()) {
43:             for (var s : repository.enabled()) {
44:                 try {
45:                     var local = automationClock.instant().atZone(ZoneId.of(s.timezone()));
46:                     int triggerHour = repository.habit(s.owner())
47:                             .filter(h -> h.active() && automationClock.instant().isBefore(h.expiresAt()))
48:                             .map(LifeReviewModels.Habit::availableHour)
49:                             .orElse(21);
50:                     if (local.getHour() >= triggerHour && repository.latest(s.owner(), local.toLocalDate()).isEmpty())
51:                         reviews.prepare(s.owner(), new LifeReviewDtos.Prepare(local.toLocalDate(), 0, false));
52:                     outreach.tick(s.owner());
53:                 } catch (RuntimeException e) { log.warn("生活复盘调度跳过：{}", e.getClass().getSimpleName()); }
54:             }
55:         } catch (RuntimeException e) { log.warn("生活复盘后台暂停：{}", e.getClass().getSimpleName()); }
56:     }
57:     /** 模型生成使用独立单线程，避免等待模型期间阻塞现实信号监测。 */
58:     void generate() {
59:         if (barrier.blocked()) return;
60:         try { reviews.tick(); }
61:         catch (RuntimeException e) { log.warn("生活复盘生成调度暂停：{}", e.getClass().getSimpleName()); }
62:     }
63:     @PreDestroy public void close() { worker.shutdownNow(); generationWorker.shutdownNow(); }
64: }

