113:     /**
114:      * 精确匹配授权时冻结的 Provider ID 与 Model ID；直接只读配置文件，
115:      * 不调用会自动初始化或改写配置的入口，也不在模型切换时静默换供应商。
116:      */
117:     private ModelSelector selector(ReviewGenerationRequest request) {
118:         if (request.providerId() == null || request.providerId().isBlank()
119:                 || request.modelName() == null || request.modelName().isBlank())
120:             throw new ReviewGenerationException(ReviewGenerationException.Kind.INVALID, "未指定复盘模型连接");
121:         LocalConfigService.ModelConfigData data;
122:         try {
123:             var path = config.getConfigPath();
124:             if (!java.nio.file.Files.isRegularFile(path) || java.nio.file.Files.size(path) > 2_000_000)
125:                 throw new ReviewGenerationException(ReviewGenerationException.Kind.UNAVAILABLE, "模型配置不可用");
126:             data = objectMapper.readValue(java.nio.file.Files.readAllBytes(path), LocalConfigService.ModelConfigData.class);
127:         } catch (ReviewGenerationException exception) {
128:             throw exception;
129:         } catch (Exception exception) {
130:             throw new ReviewGenerationException(ReviewGenerationException.Kind.UNAVAILABLE, "模型配置读取失败", exception);
131:         }
132:         if ("ACTIVE".equalsIgnoreCase(request.providerId())) {
133:             for (var candidate : data.getProviders()) {
134:                 if (candidate == null || !Boolean.TRUE.equals(candidate.getIsEnabled())
135:                         || candidate.getApiKey() == null || candidate.getApiKey().isBlank()
136:                         || candidate.getModels() == null || candidate.getModels().isEmpty()) continue;
137:                 var firstModel = candidate.getModels().stream().filter(java.util.Objects::nonNull).findFirst().orElse(null);
138:                 if (firstModel == null) continue;
139:                 String activeModelName = firstModel.getModelName() == null || firstModel.getModelName().isBlank()
140:                         ? firstModel.getName() : firstModel.getModelName();
141:                 if (activeModelName != null && !activeModelName.isBlank()) {
142:                     return new ModelSelector(candidate.getType(), activeModelName, candidate.getApiKey(), 0.2, false,
143:                             candidate.getBaseUrl(), candidate.getProtocol());
144:                 }
145:             }
146:             throw new ReviewGenerationException(ReviewGenerationException.Kind.UNAVAILABLE, "当前没有可用的已启用模型连接");
147:         }
148:         var provider = data.getProviders().stream()
149:                 .filter(item -> item != null && request.providerId().equals(item.getId()))
150:                 .findFirst()
151:                 .orElseThrow(() -> new ReviewGenerationException(ReviewGenerationException.Kind.UNAVAILABLE, "复盘模型连接已移除"));
152:         boolean exists = provider.getModels() != null && provider.getModels().stream()
153:                 .filter(java.util.Objects::nonNull)
154:                 .anyMatch(item -> request.modelName().equals(item.getModelName() == null || item.getModelName().isBlank()
155:                         ? item.getName() : item.getModelName()));
156:         if (!Boolean.TRUE.equals(provider.getIsEnabled()) || !exists || provider.getApiKey() == null
157:                 || provider.getApiKey().isBlank())
158:             throw new ReviewGenerationException(ReviewGenerationException.Kind.UNAVAILABLE, "复盘模型已关闭或凭据不可用");
159:         if (request.expectedFingerprint() != null && !request.expectedFingerprint().isBlank()
160:                 && !request.expectedFingerprint().equals(ReviewConnectionIdentity.fingerprint(provider.getId(),
161:                     request.modelName(), provider.getType(), provider.getProtocol(), provider.getBaseUrl())))
162:             throw new ReviewGenerationException(ReviewGenerationException.Kind.INVALID, "复盘接收方已变化，未发送正文");
163:         return new ModelSelector(provider.getType(), request.modelName(), provider.getApiKey(), 0.2, false,
164:                 provider.getBaseUrl(), provider.getProtocol());
165:     }
166: 
167:     /** 只向模型发送已最小化字段，Provider ID、模型名和 Key 不进入提示词。 */
168:     private String payload(ReviewGenerationRequest request) {
169:         try {
170:             var value = new java.util.LinkedHashMap<String, Object>();
171:             value.put("period", request.period());
172:             value.put("periodLabel", request.periodLabel());
173:             value.put("coverage", request.coverage());
174:             value.put("evidence", request.evidence());
175:             value.put("narratives", request.narratives());
176:             value.put("goals", request.goals());
177:             value.put("historyActions", request.historyActions());
178:             value.put("observations", request.observations());
179:             value.put("methods", request.methods());
180:             return objectMapper.writeValueAsString(value);
181:         } catch (Exception exception) {
182:             throw new ReviewGenerationException(ReviewGenerationException.Kind.INVALID, "复盘输入序列化失败", exception);
183:         }
184:     }
185: 
186:     private List<ChatResponse> invoke(Model model, ReviewGenerationRequest request, GenerateOptions options) {
187:         var messages = List.of(
188:                 SystemMessage.builder().textContent(SYSTEM_PROMPT + "\n输入预算：" + request.inputTokenBudget() + " tokens").build(),
189:                 UserMessage.builder().textContent(payload(request)).build());
190:         var timeout = Duration.ofMillis(Math.max(5_000, request.timeoutMillis()));
191:         try {
192:             return model.stream(messages, List.of(), options).collectList().block(timeout);
193:         } catch (RuntimeException exception) {
194:             if (options.getAdditionalBodyParams() != null && options.getAdditionalBodyParams().containsKey("thinking")
195:                     && !(exception instanceof ReviewGenerationException)) {
196:                 GenerateOptions fallback = GenerateOptions.builder()
197:                         .stream(false)
198:                         .temperature(0.2)
199:                         .maxTokens(Math.max(200, Math.min(4096, request.outputTokenBudget())))
200:                         .build();
201:                 return model.stream(messages, List.of(), fallback).collectList().block(timeout);
202:             }
203:             throw exception;
204:         }
205:     }
206: 
207:     private ReviewGenerationException classify(RuntimeException exception) {
208:         Throwable cause = exception;
209:         while (cause != null) {
210:             if (cause instanceof TimeoutException || cause instanceof java.util.concurrent.TimeoutException)
211:                 return new ReviewGenerationException(ReviewGenerationException.Kind.TIMEOUT, "复盘模型请求超时", exception);
212:             cause = cause.getCause();
213:         }
214:         return new ReviewGenerationException(ReviewGenerationException.Kind.UNAVAILABLE, "复盘模型调用失败", exception);
215:     }
216: 
217:     private void record(Model model, ModelSelector selector, ChatResponse response) {
218:         try {
219:             ledger.append(null, UsagePurpose.REPORT_REVIEW, response == null ? null : response.getId(),
220:                     new ModelIdentity(selector.vendor(), selector.name()), response == null ? null : response.getUsage());
221:         } catch (RuntimeException exception) {
222:             log.warn("复盘用量记录失败：type={}", exception.getClass().getSimpleName());
223:         }
224:     }
225: }

