4: /** 不自动重试写入；读取不会触发模型或投递。 */
5: async function request<T>(path: string, method = 'GET', body?: unknown): Promise<T> {
6:   let response: Response;
7:   try {
8:     response = await apiFetch(`${getApiBaseUrl()}/agent/life-reviews${path}`, {
9:       method, headers: body === undefined ? undefined : { 'Content-Type': 'application/json' },
10:       body: body === undefined ? undefined : JSON.stringify(body), signal: AbortSignal.timeout(25_000),
11:     });
12:   } catch { throw new Error('生活复盘请求未完成，请刷新核对状态后再决定是否重试'); }
13:   let result: ApiResponse<T>;
14:   try { result = await response.json() as ApiResponse<T>; }
15:   catch { throw new Error('生活复盘响应不可读取，请检查后端版本'); }
16:   if (!response.ok || !result || typeof result !== 'object' || result.code !== 200 || !Object.hasOwn(result, 'data'))
17:     throw new Error(result?.message || '生活复盘服务不可用');
18:   return result.data;
19: }
